"""GLB → 3DGS .ply conversion, on a real 32,768-Gaussian splat generated by idol-mlx (tests/fixtures/lamp.glb)."""

import json
import struct
from pathlib import Path

import numpy as np
import pytest

from idol_mlx import Splat
from idol_mlx.splat import PLY_PROPERTIES, InvalidSplatError

FIXTURE = Path(__file__).parent / "fixtures" / "lamp.glb"


@pytest.fixture(scope="module")
def splat() -> Splat:
    return Splat.from_glb(FIXTURE.read_bytes())


def read_ply(data: bytes) -> tuple[str, np.ndarray]:
    end = data.index(b"end_header\n") + len(b"end_header\n")
    header = data[:end].decode()
    rows = np.frombuffer(data[end:], dtype="<f4").reshape(-1, len(PLY_PROPERTIES))
    return header, rows


def test_reads_every_gaussian(splat: Splat):
    assert len(splat) == 32_768
    assert splat.positions.shape == (32_768, 3)
    assert splat.rotations.shape == (32_768, 4)
    assert splat.opacities.shape == (32_768,)


def test_rotations_are_unit_quaternions(splat: Splat):
    norms = np.linalg.norm(splat.rotations, axis=1)
    assert np.allclose(norms, 1.0, atol=1e-3)


def test_ply_header_is_standard_3dgs(splat: Splat):
    header, rows = read_ply(splat.to_ply())
    assert header.startswith("ply\nformat binary_little_endian 1.0\nelement vertex 32768\n")
    assert [line.split()[-1] for line in header.splitlines() if line.startswith("property")] == PLY_PROPERTIES
    assert rows.shape == (32_768, 17)


def test_ply_values_round_trip(splat: Splat):
    _, rows = read_ply(splat.to_ply())
    columns = {name: rows[:, i] for i, name in enumerate(PLY_PROPERTIES)}

    xyz = np.stack([columns["x"], columns["y"], columns["z"]], axis=1)
    assert np.array_equal(xyz, splat.positions)

    # log scales and logit opacities, as 3DGS stores them
    scales = np.exp(np.stack([columns[f"scale_{i}"] for i in range(3)], axis=1))
    assert np.allclose(scales, np.maximum(splat.scales, 1e-7), rtol=1e-5)
    opacity = 1 / (1 + np.exp(-columns["opacity"]))
    assert np.allclose(opacity, np.clip(splat.opacities, 1e-7, 1 - 1e-7), atol=1e-5)

    # glTF stores (x, y, z, w); 3DGS wants w first
    wxyz = np.stack([columns[f"rot_{i}"] for i in range(4)], axis=1)
    assert np.array_equal(wxyz, splat.rotations[:, [3, 0, 1, 2]])


def test_save_picks_format_from_extension(splat: Splat, tmp_path: Path):
    assert splat.save(tmp_path / "a.glb").read_bytes() == FIXTURE.read_bytes()
    assert splat.save(tmp_path / "a.ply").read_bytes()[:3] == b"ply"
    with pytest.raises(ValueError, match="use .ply or .glb"):
        splat.save(tmp_path / "a.obj")


def test_rejects_files_that_are_not_glb():
    with pytest.raises(ValueError, match="Not a GLB"):
        Splat.from_glb(b"ply\nformat binary_little_endian 1.0\n")


def _with_header(glb: bytes, header: str) -> bytes:
    """Rebuild a GLB with a replacement JSON chunk, keeping the binary chunk."""
    json_length = struct.unpack_from("<I", glb, 12)[0]
    rest = glb[20 + json_length :]
    chunk = header.encode()
    chunk += b" " * (-len(chunk) % 4)
    body = struct.pack("<II", len(chunk), 0x4E4F534A) + chunk + rest
    return b"glTF" + struct.pack("<II", 2, 12 + len(body)) + body


def test_rejects_nan_in_the_header_as_mlx_serve_writes_it():
    glb = FIXTURE.read_bytes()
    doc = json.loads(glb[20 : 20 + struct.unpack_from("<I", glb, 12)[0]])
    doc["accessors"][0]["min"][0] = "__NAN__"
    broken = _with_header(glb, json.dumps(doc).replace('"__NAN__"', "nan"))
    with pytest.raises(InvalidSplatError, match="isn't valid JSON"):
        Splat.from_glb(broken)


def test_rejects_nan_positions():
    glb = bytearray(FIXTURE.read_bytes())
    json_length = struct.unpack_from("<I", glb, 12)[0]
    doc = json.loads(glb[20 : 20 + json_length])
    position_view = doc["bufferViews"][doc["accessors"][0]["bufferView"]]
    first_float = 20 + json_length + 8 + position_view.get("byteOffset", 0)
    glb[first_float : first_float + 4] = struct.pack("<f", float("nan"))
    with pytest.raises(InvalidSplatError, match="NaN"):
        Splat.from_glb(bytes(glb))


def test_flags_collapsed_generations(splat: Splat):
    splat.check_not_empty()  # the real fixture is healthy
    assert splat.opaque_fraction > 0.5

    collapsed = Splat.from_glb(FIXTURE.read_bytes())
    collapsed.opacities = np.zeros_like(collapsed.opacities)
    collapsed.opacities[:10] = 1.0  # a handful of stray Gaussians, like the collapsed rifle in the Met pilot
    with pytest.raises(InvalidSplatError, match="collapsed"):
        collapsed.check_not_empty()
